import dayjs from "dayjs";
export default {
  name: 'userInfo',
  props: {
    psInfo: Object,
    workMemberInfo: Object,
    workClientInfo: Object
  },
  filters: {
    timeFormat: function timeFormat(value) {
      if (!value) {
        return '-';
      }
      return dayjs(value * 1000).format('YYYY-MM-DD HH:mm:ss');
    },
    gender: function gender(value) {
      if (value == 1) {
        return '男';
      } else if (value == 2) {
        return '女';
      } else {
        return '未知';
      }
    }
  },
  computed: {
    hasExtendInfo: function hasExtendInfo() {
      return this.psInfo.extend_info.some(function (item) {
        return item.value;
      });
    }
  }
};
